# Checks run inside the app page by the probe (one line of JavaScript each, written without spaces so each
# stays one launch argument). Each returns a short text that lands in the probe's notes.
FIRST="(function(d,q,t,c,g){q=function(s,e,b){e=d.querySelector(s);if(!e)return'none';b=e.getBoundingClientRect();return[Math.round(b.left),Math.round(b.top),Math.round(b.width),Math.round(b.height)].join(',')};g=function(s){return(getComputedStyle(d.querySelector(s)).backgroundColor||'').split('\x20').join('')};t=d.querySelector('#splash-terms');c=d.querySelector('.splash-card');return['shown='+!d.querySelector('#splash').hidden,'win='+innerWidth+'x'+innerHeight,'band='+q('#band'),'card='+q('.splash-card'),'cardScroll='+(c.scrollHeight-c.clientHeight),'h1='+q('#splash-title'),'terms='+q('#splash-terms'),'more='+(t.scrollHeight-t.clientHeight),'line='+q('#splash-terms+p'),'agree='+q('#agree'),'setup='+q('#agree-setup'),'logo='+q('.splash-card\x20img'),'dark='+matchMedia('(prefers-color-scheme:dark)').matches,'bandBg='+g('#band'),'cardBg='+g('.splash-card'),'termsBg='+g('#splash-terms'),'font='+getComputedStyle(t).fontSize].join(';')})(document)"
FIRST_END="(function(d,t,p,a,b){t=d.querySelector('#splash-terms');t.scrollTop=t.scrollHeight;p=t.querySelectorAll('p');p=p[p.length-1];a=p.getBoundingClientRect();b=t.getBoundingClientRect();return['scrollTop='+Math.round(t.scrollTop),'max='+(t.scrollHeight-t.clientHeight),'lastBottom='+Math.round(a.bottom),'boxTop='+Math.round(b.top),'boxBottom='+Math.round(b.bottom),'lastText='+p.textContent.slice(-30).split('\x20').join('_')].join(';')})(document)"
SETTINGS="(function(d,m){d.querySelector('#menu-btn').click();m=d.querySelector('#menu\x20[data-go=settings]');if(!m)return'no-settings-link';m.click();setTimeout(function(r){r=[].map.call(d.querySelectorAll('#pane-settings\x20.set-row'),function(e,b){b=e.getBoundingClientRect();return(e.hidden?'(hidden)':'')+e.textContent.replace(/\s+/g,'_').slice(0,34)+'@'+Math.round(b.top)+'h'+Math.round(b.height)});window.webkit.messageHandlers.log.postMessage('rows:'+r.join('|')+';theme='+d.querySelector('#set-theme').value+';dark='+matchMedia('(prefers-color-scheme:dark)').matches)},1500);return'opened'})(document)"
MAIN="(function(d,g){g=function(s,e){e=d.querySelector(s);return(e?getComputedStyle(e).backgroundColor:'none').split('\x20').join('')};return['dark='+matchMedia('(prefers-color-scheme:dark)').matches,'theme='+d.documentElement.getAttribute('data-theme'),'bandBg='+g('#band'),'searchBg='+g('.searchbar'),'sheetBg='+g('#sheet'),'cls='+d.body.className,'win='+innerWidth+'x'+innerHeight].join(';')})(document)"
